import javax.xml.parsers.DocumentBuilderFactory

class Bad {
    companion object {
        val dbFactory: DocumentBuilderFactory = DocumentBuilderFactory.newInstance() // bad: not thread-safe
    }
}

import javax.xml.transform.TransformerFactory

object XmlUtils {
    val tf: TransformerFactory = TransformerFactory.newInstance() // bad
}

import javax.xml.parsers.DocumentBuilderFactory

class Good {
    fun parse(xml: String) {
        val dbFactory = DocumentBuilderFactory.newInstance() // ok: local, thread-safe
        val db = dbFactory.newDocumentBuilder()
    }
}

import javax.xml.parsers.SAXParserFactory

fun parseAll(xmlList: List<String>) =
    xmlList.map {
        SAXParserFactory.newInstance().newSAXParser() // ok: local per invocation
    }
